77	pub enum MarkdownPreviewMode {
78	    /// The preview will always show the contents of the provided editor.
79	    Default,
80	    /// The preview will "follow" the currently active editor.
81	    Follow,
82	}
83	
84	impl MarkdownPreviewMode {
85	    fn to_db(self) -> i64 {
86	        match self {
87	            Self::Default => 0,
88	            Self::Follow => 1,
89	        }
90	    }
91	
92	    fn from_db(value: i64) -> Self {
93	        match value {
94	            1 => Self::Follow,
95	            _ => Self::Default,
96	        }
97	    }
98	}
