            wrap_button_visibility: markdown::WrapButtonVisibility::Hidden,
            border: false,
        })
        .scroll_handle(self.scroll_handle.clone())
        .show_root_block_markers()
        .image_resolver({
            let base_directory = self.base_directory.clone();
            move |dest_url, cx| {
                resolve_preview_image(
